installer-gui-script.script:
function found(name) {
  return system.files.fileExistsAtPath('/opt/homebrew/bin/' + name) || system.files.fileExistsAtPath('/usr/local/bin/' + name);
}
function checkAgents() {
  if (system.compareVersions(system.version.ProductVersion, '14.0') < 0) {
    my.result.title='Unsupported macOS version';
    my.result.message='CatchLessons requires macOS 14 or later.';
    my.result.type='Fatal';
    return false;
  }
  var missing=[];
  if (!found('codex')) missing.push('Codex');
  if (!found('claude')) missing.push('Claude');
  if (missing.length) {
    my.result.title='Agent CLI check';
    my.result.message=missing.join(', ') + ' was not found in standard system locations. Install and sign in to the agent you use. User-specific paths may still be detected by CatchLessons after installation.';
    my.result.type='Warning';
    return false;
  }
  return true;
}
